import json,hashlib,re,xml.etree.ElementTree as ET
from pathlib import Path
q=Path(__file__).parent;p=q.parent/'fieldlog-public-pair18-ime-save-r188'
task=json.loads((p/'saved-keyboard-task.json').read_text());label=f"{task['position']+1}. {task['title']} · {'Completed' if task['completed'] else 'Not completed'}"
raw=(p/'fresh-visible-task-3.stdout').read_bytes();nodes=list(ET.fromstring(raw).iter('node'));matches=[n.attrib for n in nodes if n.attrib.get('class')=='android.widget.TextView' and n.attrib.get('text')==label];assert len(matches)==1
bounds=list(map(int,re.findall(r'-?\d+',matches[0]['bounds'])));assert len(bounds)==4 and bounds[0]>=0 and bounds[1]>=0 and bounds[2]>bounds[0] and bounds[3]>bounds[1]
prior=json.loads((p/'owned-before.stdout').read_text());final=json.loads((p/'owned-final-durable.stdout').read_text());commands=json.loads((p/'commands.json').read_text());observations=[x['name'] for x in commands if x['name'].startswith('durable-six-ten-')];saved=json.loads((p/(observations[-1]+'.stdout')).read_text());assert saved==final and len(final['tasks'])==6 and len(final['outbox'])==10;assert final['tasks'][:5]==prior['tasks'] and final['outbox'][:9]==prior['outbox'];assert final['tasks'][-1]==task and task['title']=='Test'
r=json.loads((p/'result.json').read_text());assert r['error']=="RuntimeError('Control not visible: fresh-visible-task')" and r['ownedSerialAbsent'] and r['externalBaselineUnchanged'] and r['emulatorExitCode']==0 and not r['nativeFatalOrSurfaceFailure']
assert 'Saved on device' in (p/'saved-on-device-0.stdout').read_text();assert '10 pending changes' in (p/'fresh-process-form.stdout').read_text()
for wrong in ['Test','5. Test · Not completed','6. Test · Completed','6. Tests · Not completed']:assert not any(n.attrib.get('text')==wrong for n in nodes)
(q/'native-task-node.json').write_text(json.dumps(matches[0],indent=2)+'\n')
